import {getClient} from './shared.js';
import {BUILD_CATEGORIES,ITEM_CATEGORIES,validateItems,itemPool,drawBuild,searchItems} from './build-core.js';
const $=s=>document.querySelector(s);
let items=[],category='Todos',busy=false,drawn=false;
const node=(tag,cls,text)=>{const n=document.createElement(tag);n.className=cls||'';if(text!=null)n.textContent=text;return n;};
function card(item,index){
 const boot=index===5,article=node('article',`item-card${boot?' boot-slot':''}`);
 if(index!=null)article.append(node('p','slot-label',boot?'BOTA':`ITEM ${index+1}`));
 const art=node('div','item-art'),img=node('img');img.alt=item.name;img.width=160;img.height=160;img.loading=index==null?'lazy':'eager';img.src=item.image_url;
 img.onerror=()=>{img.hidden=true;art.append(node('span','image-unavailable','Imagem indisponível'));};art.append(img);article.append(art,node('h3','',item.name));
 const badges=node('div','badges');item.categories.forEach(c=>badges.append(node('span','badge',c)));article.append(badges,node('p','item-price',item.price==null?'Preço não informado':`${item.price.toLocaleString('pt-BR')} ouro`));return article;
}
function filters(){const root=$('#build-categories');root.replaceChildren();['Todos',...BUILD_CATEGORIES].forEach(c=>{const b=node('button',`route${c===category?' active':''}`,c);b.type='button';b.disabled=busy;b.setAttribute('aria-pressed',String(c===category));b.onclick=()=>{category=c;filters();};root.append(b);});const pool=itemPool(items,category);$('#build-pool').textContent=`${pool.length} itens elegíveis · ${items.filter(i=>i.categories.includes('Botas')).length} botas`;$('#draw-build').disabled=busy||pool.length<5||!items.some(i=>i.categories.includes('Botas'));}
function catalog(){const matches=searchItems(items,$('#item-category').value,$('#item-search').value);$('#item-count').textContent=String(matches.length);$('#items-list').replaceChildren(...matches.map(i=>card(i)));if(!matches.length)$('#items-list').append(node('p','muted','Nenhum item encontrado. Tente outro nome ou categoria.'));}
async function load(){if(busy)return;$('#items-status').textContent='Carregando catálogo de itens…';$('#retry-items').hidden=true;try{const client=await getClient();let rows=[];for(let from=0;;from+=1000){const {data,error}=await client.from('wr_items').select('id,name,price,categories,image_path,is_boot,active').eq('active',true).order('id').range(from,from+999);if(error)throw error;rows.push(...data);if(data.length<1000)break;}items=validateItems(rows).map(i=>({...i,image_url:client.storage.from('wr-item-images').getPublicUrl(i.image_path).data.publicUrl}));filters();catalog();$('#items-status').textContent='';}catch{$('#items-status').textContent='Não foi possível carregar os itens. Tente novamente.';$('#retry-items').hidden=false;}}
$('#draw-build').onclick=async()=>{if(busy)return;busy=true;const chosenCategory=category;filters();$('#draw-build').textContent='Sorteando…';$('#build-result').setAttribute('aria-busy','true');$('#build-result').classList.add('rolling');try{const build=drawBuild(items,chosenCategory);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?0:360));$('#build-result').replaceChildren(...build.map((item,index)=>card(item,index)));$('#build-announcement').textContent=`Build de ${chosenCategory}: ${build.slice(0,5).map(i=>i.name).join(', ')}. Bota: ${build[5].name}.`;drawn=true;}catch(e){$('#build-announcement').textContent=e.message;}finally{busy=false;$('#build-result').classList.remove('rolling');$('#build-result').setAttribute('aria-busy','false');$('#draw-build').textContent=drawn?'Sortear Novamente':'Sortear Build';filters();}};
ITEM_CATEGORIES.forEach(c=>{const o=node('option','',c);o.value=c;$('#item-category').append(o);});
$('#item-search').addEventListener('input',catalog);$('#item-category').addEventListener('change',catalog);$('#retry-items').onclick=load;
load();window.addEventListener('online',()=>{if(!items.length)load();});
